#!/usr/bin/env bash
# Stage 0: kind cluster + local registry (idempotent, project-scoped).
set -euo pipefail
# shellcheck source=lib/common.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/common.sh"

render_kind_config() {
  cat >"$STATE_DIR/kind-config.yaml" <<EOF
# Generated by scripts/cluster.sh - edit the script, not this file.
kind: Cluster
apiVersion: kind.x-k8s.io/v1alpha4
name: ${CLUSTER_NAME}
networking:
  # Fixed API port. With kind's default (random port) Docker Desktop + WSL2 intermittently fails
  # with "bind: Only one usage of each socket address", because WSL mirrors kind's probe port to Windows.
  apiServerAddress: "127.0.0.1"
  apiServerPort: ${API_PORT}
nodes:
  - role: control-plane
    image: ${KIND_NODE_IMAGE}
    # Host ports -> NodePorts. Bound to loopback only: nothing is exposed to your LAN.
    extraPortMappings:
      - { containerPort: 30080, hostPort: ${APP_PORT},        listenAddress: "127.0.0.1", protocol: TCP }
      - { containerPort: 30081, hostPort: ${ARGOCD_PORT},     listenAddress: "127.0.0.1", protocol: TCP }
      - { containerPort: 30300, hostPort: ${GRAFANA_PORT},    listenAddress: "127.0.0.1", protocol: TCP }
      - { containerPort: 30900, hostPort: ${PROMETHEUS_PORT}, listenAddress: "127.0.0.1", protocol: TCP }
EOF
}

ensure_registry() {
  if [[ "$(docker inspect -f '{{.State.Running}}' "$REGISTRY_NAME" 2>/dev/null || true)" == "true" ]]; then
    ok "registry $REGISTRY_NAME running"; return
  fi
  if docker inspect "$REGISTRY_NAME" >/dev/null 2>&1; then
    docker start "$REGISTRY_NAME" >/dev/null; ok "registry $REGISTRY_NAME restarted"; return
  fi
  port_in_use "$REGISTRY_PORT" && die "port $REGISTRY_PORT is in use; set REGISTRY_PORT=<free port>"
  docker run -d --restart=always --name "$REGISTRY_NAME" --label releaseops.project=true \
    -p "127.0.0.1:${REGISTRY_PORT}:5000" "$REGISTRY_IMAGE" >/dev/null
  ok "registry $REGISTRY_NAME created on 127.0.0.1:${REGISTRY_PORT}"
}

ensure_cluster() {
  render_kind_config
  if cluster_exists; then
    ok "kind cluster '$CLUSTER_NAME' exists - reusing"
  else
    for p in "$API_PORT" "$APP_PORT" "$ARGOCD_PORT" "$GRAFANA_PORT" "$PROMETHEUS_PORT"; do
      port_in_use "$p" && die "host port $p is already in use (override APP_PORT/ARGOCD_PORT/GRAFANA_PORT/PROMETHEUS_PORT)"
    done
    step "creating kind cluster '$CLUSTER_NAME' ($KIND_NODE_IMAGE)"
    # kind picks a random API port that can collide on Docker Desktop: retry
    local attempt
    for attempt in 1 2 3 4; do
      kind create cluster --config "$STATE_DIR/kind-config.yaml" --kubeconfig "$KUBECONFIG_FILE" --wait 120s && break
      [[ $attempt -eq 4 ]] && die "kind could not create the cluster after $attempt attempts"
      warn "cluster creation failed (attempt $attempt) - retrying"; sleep 3
    done
  fi
  # Always rewrite our private kubeconfig
  kind export kubeconfig --name "$CLUSTER_NAME" --kubeconfig "$KUBECONFIG_FILE" >/dev/null
  chmod 600 "$KUBECONFIG_FILE"
}

wire_registry_into_cluster() {
  # Let nodes resolve localhost:<port> to the registry container
  local node dir="/etc/containerd/certs.d/localhost:${REGISTRY_PORT}"
  for node in $(kind get nodes --name "$CLUSTER_NAME"); do
    docker exec "$node" mkdir -p "$dir"
    printf '[host."http://%s:5000"]\n' "$REGISTRY_NAME" | docker exec -i "$node" sh -c "cat > '$dir/hosts.toml'"
  done
  if [[ "$(docker inspect -f '{{json .NetworkSettings.Networks.kind}}' "$REGISTRY_NAME")" == "null" ]]; then
    docker network connect kind "$REGISTRY_NAME"
  fi
  ok "registry wired into the cluster network"
}

main() {
  need docker; need kind; need kubectl
  step "local registry"; ensure_registry
  step "kind cluster"; ensure_cluster
  wire_registry_into_cluster
  step "waiting for the node to be Ready"
  k wait --for=condition=Ready node --all --timeout=180s >/dev/null
  ok "cluster ready: $(k get nodes -o jsonpath='{.items[0].status.nodeInfo.kubeletVersion}') (context $KIND_CONTEXT)"
}

[[ "${BASH_SOURCE[0]}" == "$0" ]] && main "$@"
true
